62	@RestController
63	@CrossOrigin(exposedHeaders = "errors, content-type")
64	@RequestMapping("/api")
65	public class OwnerRestControllerV1 implements OwnersApi {
66	
67	    private final ClinicService clinicService;
68	
69	    private final OwnerMapper ownerMapper;
70	
71	    private final PetMapper petMapper;
72	
73	    private final VisitMapper visitMapper;
74	
75	    /**
76	     * Pattern for a syntactically valid email address: a non-empty local part, an {@code @},
77	     * and a domain containing at least one dot, with no whitespace in any segment.
78	     */
79	    private static final Pattern EMAIL_PATTERN = Pattern.compile("^[^@\\s]+@[^@\\s]+\\.[^@\\s]+$");
80	
81	    /**
82	     * Expansions of the common street-type abbreviations recognised by {@link #normalizeAddress}.
83	     * Keys and values are upper-case, matching the casing the address is folded to before expansion.
84	     */
85	    private static final Map<String, String> ADDRESS_ABBREVIATIONS = Map.of(
86	        "ST", "STREET",
87	        "RD", "ROAD",
88	        "AVE", "AVENUE");
89	
90	    public OwnerRestControllerV1(ClinicService clinicService,
91	                                 OwnerMapper ownerMapper,
92	                                 PetMapper petMapper,
93	                                 VisitMapper visitMapper) {
94	        this.clinicService = clinicService;
95	        this.ownerMapper = ownerMapper;
96	        this.petMapper = petMapper;
97	        this.visitMapper = visitMapper;
98	    }
99	
100	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
101	    @Override
102	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
103	        Collection<Owner> owners;
104	        if (lastName != null) {
105	            owners = this.clinicService.findOwnerByLastName(lastName);
106	        } else {
107	            owners = this.clinicService.findAllOwners();
108	        }
109	        if (owners.isEmpty()) {
110	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
111	        }
112	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
113	    }
114	
115	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
116	    @Override
117	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
118	        Owner owner = this.clinicService.findOwnerById(ownerId);
119	        if (owner == null) {
120	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
121	        }
122	        return new ResponseEntity<>(ownerMapper.toOwnerDto(owner), HttpStatus.OK);
123	    }
124	
125	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
126	    @Override
127	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
128	        validateRequiredFields(ownerFieldsDto);
129	        HttpHeaders headers = new HttpHeaders();
130	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
131	        owner.setAddress(normalizeAddress(ownerFieldsDto.getAddress()));
132	        if (Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold())) {
133	            joinHousehold(owner);
134	        } else {
135	            requireUniqueHousehold(owner.getLastName(), owner.getAddress());
136	        }
137	        String telephone = normalizeTelephone(ownerFieldsDto.getTelephone());
138	        requireUniqueTelephone(telephone);
139	        owner.setTelephone(telephone);
140	        owner.setEmail(normalizeEmail(ownerFieldsDto.getEmail()));
141	        owner.setCustomerCode(generateCustomerCode(owner.getLastName()));
142	        owner.setNamesakeCount(countNamesakes(owner.getFirstName(), owner.getLastName()));
143	        this.clinicService.saveOwner(owner);
144	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
145	        headers.setLocation(UriComponentsBuilder.newInstance()
146	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
147	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
148	    }
149	
150	    /**
151	     * Generates the customer code for a newly created owner, formatted {@code '<LAST3>-<NNNN>'}.
152	     * {@code LAST3} is the upper-cased first three letters of the last name and {@code NNNN} is a
153	     * global, 4-digit zero-padded sequence equal to one more than the current number of owners
154	     * (e.g. {@code 'SMI-0007'}).
155	     *
156	     * @param lastName the owner's last name
157	     * @return the generated customer code
158	     */
159	    private String generateCustomerCode(String lastName) {
160	        String last3 = lastName.substring(0, Math.min(3, lastName.length())).toUpperCase(Locale.ROOT);
161	        int sequence = this.clinicService.findAllOwners().size() + 1;
162	        return String.format("%s-%04d", last3, sequence);
163	    }
164	
165	    /**
166	     * Counts the existing owners that already share the given first name and last name, compared
167	     * case-insensitively. This is evaluated before the new owner is saved, so it reflects only the
168	     * owners that existed prior to this create.
169	     *
170	     * @param firstName the first name of the owner being created
171	     * @param lastName the last name of the owner being created
172	     * @return the number of pre-existing namesakes
173	     */
174	    private int countNamesakes(String firstName, String lastName) {
175	        return (int) this.clinicService.findAllOwners().stream()
176	            .filter(existing -> equalsIgnoreCase(existing.getFirstName(), firstName)
177	                && equalsIgnoreCase(existing.getLastName(), lastName))
178	            .count();
179	    }
180	
181	    /**
182	     * Compares two possibly-{@code null} strings for equality, ignoring case. Two {@code null} values
183	     * are considered equal and a {@code null} is never equal to a non-{@code null} value.
184	     *
185	     * @param a the first value, possibly {@code null}
186	     * @param b the second value, possibly {@code null}
187	     * @return whether the values are equal ignoring case
188	     */
189	    private boolean equalsIgnoreCase(String a, String b) {
190	        return a == null ? b == null : a.equalsIgnoreCase(b);
191	    }
192	
193	    /**
194	     * Rejects an owner payload that is missing or blank in any required field. Bean Validation
195	     * (via {@code @Valid}) already rejects {@code null} values and fields that violate their size
196	     * or pattern constraints; this guard additionally rejects whitespace-only values for fields
197	     * (such as address and city) that have no pattern constraint, so that no required field is blank.
198	     *
199	     * @param ownerFieldsDto the submitted owner fields
200	     * @throws InvalidOwnerFieldsException if one or more required fields are missing or blank
201	     */
202	    private void validateRequiredFields(OwnerFieldsDto ownerFieldsDto) {
203	        List<String> invalidFields = new ArrayList<>();
204	        if (!StringUtils.hasText(ownerFieldsDto.getFirstName())) {
205	            invalidFields.add("firstName");
206	        }
207	        if (!StringUtils.hasText(ownerFieldsDto.getLastName())) {
208	            invalidFields.add("lastName");
209	        }
210	        if (!StringUtils.hasText(normalizeAddress(ownerFieldsDto.getAddress()))) {
211	            invalidFields.add("address");
212	        }
213	        if (!StringUtils.hasText(ownerFieldsDto.getCity())) {
214	            invalidFields.add("city");
215	        }
216	        if (!StringUtils.hasText(ownerFieldsDto.getTelephone())) {
217	            invalidFields.add("telephone");
218	        }
219	        if (!invalidFields.isEmpty()) {
220	            throw new InvalidOwnerFieldsException(invalidFields);
221	        }
222	    }
223	
224	    /**
225	     * Normalizes a submitted telephone number to E.164 form and requires the result to be valid. The
226	     * normalized E.164 string (a leading {@code '+'} followed by country code and national digits) is
227	     * what gets stored and returned.
228	     *
229	     * @param telephone the raw telephone value from the request
230	     * @return the normalized E.164 telephone number
231	     * @throws InvalidOwnerFieldsException if the value cannot form a valid E.164 number
232	     */
233	    private String normalizeTelephone(String telephone) {
234	        String e164 = toE164(telephone);
235	        if (e164 == null) {
236	            throw new InvalidOwnerFieldsException(List.of("telephone"));
237	        }
238	        return e164;
239	    }
240	
241	    /**
242	     * Converts a telephone value to E.164 form, giving the single authoritative definition of a
243	     * telephone's normalized form. Spaces, dashes and brackets are stripped. A leading {@code '+'}
244	     * and its country code are kept when present; otherwise country code {@code '+61'} is assumed and
245	     * a single leading {@code '0'} is dropped from the national digits. The result is valid only when
246	     * it contains 8 to 15 digits after the {@code '+'}.
247	     *
248	     * <p>Returns {@code null} rather than throwing when the value cannot form a valid E.164 number, so
249	     * it is safe to apply to already-stored (possibly legacy) values when comparing them.
250	     *
251	     * @param telephone the raw telephone value, possibly {@code null}
252	     * @return the E.164 string, or {@code null} if the value cannot form a valid E.164 number
253	     */
254	    private String toE164(String telephone) {
255	        if (telephone == null) {
256	            return null;
257	        }
258	        String cleaned = telephone.replaceAll("[ \\-()]", "");
259	        String digits;
260	        if (cleaned.startsWith("+")) {
261	            digits = cleaned.substring(1);
262	        } else {
263	            String national = cleaned.startsWith("0") ? cleaned.substring(1) : cleaned;
264	            digits = "61" + national;
265	        }
266	        if (!digits.matches("[0-9]{8,15}")) {
267	            return null;
268	        }
269	        return "+" + digits;
270	    }
271	
272	    /**
273	     * Normalizes an optional owner email. An absent (null or blank) email is allowed and yields
274	     * {@code null}. When present, the value must be a syntactically valid address; it is then stored
275	     * and returned lower-cased.
276	     *
277	     * @param email the raw email value from the request, possibly {@code null}
278	     * @return the lower-cased email, or {@code null} when none was supplied
279	     * @throws InvalidOwnerFieldsException if a value is present but not a valid email address
280	     */
281	    private String normalizeEmail(String email) {
282	        if (!StringUtils.hasText(email)) {
283	            return null;
284	        }
285	        String trimmed = email.trim();
286	        if (!EMAIL_PATTERN.matcher(trimmed).matches()) {
287	            throw new InvalidOwnerFieldsException(List.of("email"));
288	        }
289	        return trimmed.toLowerCase(Locale.ROOT);
290	    }
291	
292	    /**
293	     * Rejects a telephone number whose E.164 form is already used by an existing owner. This enforces
294	     * that no two owners share the same E.164 telephone. Existing values are compared by their E.164
295	     * form; a stored value that cannot form a valid E.164 number is compared as-is.
296	     *
297	     * @param telephone the normalized (E.164) telephone of the owner being created
298	     * @throws DuplicateTelephoneException if another owner already has this E.164 telephone
299	     */
300	    private void requireUniqueTelephone(String telephone) {
301	        boolean inUse = this.clinicService.findAllOwners().stream()
302	            .map(Owner::getTelephone)
303	            .filter(existing -> existing != null)
304	            .map(existing -> {
305	                String e164 = toE164(existing);
306	                return e164 != null ? e164 : existing;
307	            })
308	            .anyMatch(telephone::equals);
309	        if (inUse) {
310	            throw new DuplicateTelephoneException(telephone);
311	        }
312	    }
313	
314	    /**
315	     * Rejects an owner whose last name and address match those of an existing owner, where both are
316	     * compared case-insensitively and with runs of whitespace collapsed to a single space (a shared
317	     * household). The caller skips this check when the request opts in via {@code sharesHousehold}.
318	     *
319	     * @param lastName the last name of the owner being created
320	     * @param address the address of the owner being created
321	     * @throws DuplicateHouseholdException if another owner shares the same last name and address
322	     */
323	    private void requireUniqueHousehold(String lastName, String address) {
324	        if (!findHouseholdMembers(lastName, address).isEmpty()) {
325	            throw new DuplicateHouseholdException(lastName, address);
326	        }
327	    }
328	
329	    /**
330	     * Returns the existing owners that belong to the same household as the given last name and
331	     * address, i.e. those whose last name and address match case-insensitively and with runs of
332	     * whitespace collapsed to a single space.
333	     *
334	     * @param lastName the last name to match
335	     * @param address the address to match
336	     * @return the matching owners (possibly empty, never {@code null})
337	     */
338	    private List<Owner> findHouseholdMembers(String lastName, String address) {
339	        String normalizedLastName = normalizeForHousehold(lastName);
340	        String normalizedAddress = normalizeAddress(address);
341	        return this.clinicService.findAllOwners().stream()
342	            .filter(existing -> normalizeForHousehold(existing.getLastName()).equals(normalizedLastName)
343	                && normalizeAddress(existing.getAddress()).equals(normalizedAddress))
344	            .toList();
345	    }
346	
347	    /**
348	     * Joins the owner being created to the shared household of any existing owner(s) that have the
349	     * same last name and address (compared case-insensitively with collapsed whitespace). Every
350	     * member of the household - the existing owners and the new one - is assigned the same stable
351	     * {@code householdId}, so the shared identifier can be read back from any of them.
352	     *
353	     * <p>When no existing owner shares the household there is nobody to share an identifier with, so
354	     * the owner is left without a {@code householdId}.
355	     *
356	     * @param owner the owner being created, whose {@code householdId} is set when a household is joined
357	     */
358	    private void joinHousehold(Owner owner) {
359	        List<Owner> members = findHouseholdMembers(owner.getLastName(), owner.getAddress());
360	        if (members.isEmpty()) {
361	            return;
362	        }
363	        String householdId = computeHouseholdId(owner.getLastName(), owner.getAddress());
364	        owner.setHouseholdId(householdId);
365	        for (Owner member : members) {
366	            if (!householdId.equals(member.getHouseholdId())) {
367	                member.setHouseholdId(householdId);
368	                this.clinicService.saveOwner(member);
369	            }
370	        }
371	    }
372	
373	    /**
374	     * Computes the stable, shared household identifier for a last name and address. The value is
375	     * derived deterministically from the normalized (case-insensitive, whitespace-collapsed) last
376	     * name and address, so every owner in the same household computes the same identifier.
377	     *
378	     * @param lastName the last name of the household
379	     * @param address the address of the household
380	     * @return the household identifier, formatted {@code 'HH-<12 upper-case hex digits>'}
381	     */
382	    private String computeHouseholdId(String lastName, String address) {
383	        String key = normalizeForHousehold(lastName) + "\n" + normalizeAddress(address);
384	        try {
385	            byte[] digest = MessageDigest.getInstance("SHA-256")
386	                .digest(key.getBytes(StandardCharsets.UTF_8));
387	            StringBuilder hex = new StringBuilder();
388	            for (int i = 0; i < 6; i++) {
389	                hex.append(String.format("%02X", digest[i]));
390	            }
391	            return "HH-" + hex;
392	        } catch (NoSuchAlgorithmException e) {
393	            throw new IllegalStateException("SHA-256 algorithm not available", e);
394	        }
395	    }
396	
397	    /**
398	     * Normalizes a value for case-insensitive, whitespace-collapsed household comparison: leading and
399	     * trailing whitespace is trimmed, any internal run of whitespace is collapsed to a single space,
400	     * and the result is lower-cased. A {@code null} value normalizes to an empty string.
401	     *
402	     * @param value the raw value, possibly {@code null}
403	     * @return the normalized value
404	     */
405	    private String normalizeForHousehold(String value) {
406	        return collapseWhitespace(value).toLowerCase(Locale.ROOT);
407	    }
408	
409	    /**
410	     * Trims leading and trailing whitespace and collapses any internal run of whitespace to a single
411	     * space, giving the single definition of that step shared by the owner normalizers. A {@code null}
412	     * value yields an empty string.
413	     *
414	     * @param value the raw value, possibly {@code null}
415	     * @return the trimmed, whitespace-collapsed value
416	     */
417	    private String collapseWhitespace(String value) {
418	        if (value == null) {
419	            return "";
420	        }
421	        return value.trim().replaceAll("\\s+", " ");
422	    }
423	
424	    /**
425	     * Normalizes an owner's address to its canonical, stored-and-returned form: leading and trailing
426	     * whitespace is trimmed, any internal run of whitespace is collapsed to a single space, the result
427	     * is upper-cased, and common street-type abbreviations are expanded as whole words
428	     * ({@code ST -> STREET}, {@code RD -> ROAD}, {@code AVE -> AVENUE}). A {@code null} or
429	     * blank-after-collapsing value normalizes to an empty string. The transformation is idempotent, so
430	     * applying it to an already-normalized (or legacy) value is safe when comparing addresses.
431	     *
432	     * @param address the raw address value, possibly {@code null}
433	     * @return the normalized address
434	     */
435	    private String normalizeAddress(String address) {
436	        String collapsed = collapseWhitespace(address).toUpperCase(Locale.ROOT);
437	        if (collapsed.isEmpty()) {
438	            return "";
439	        }
440	        String[] tokens = collapsed.split(" ");
441	        StringBuilder normalized = new StringBuilder();
442	        for (int i = 0; i < tokens.length; i++) {
443	            if (i > 0) {
444	                normalized.append(' ');
445	            }
446	            normalized.append(ADDRESS_ABBREVIATIONS.getOrDefault(tokens[i], tokens[i]));
447	        }
448	        return normalized.toString();
449	    }
450	
451	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
452	    @Override
453	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
454	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
455	        if (currentOwner == null) {
456	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
457	        }
458	        currentOwner.setAddress(ownerFieldsDto.getAddress());
459	        currentOwner.setCity(ownerFieldsDto.getCity());
460	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
461	        currentOwner.setLastName(ownerFieldsDto.getLastName());
462	        currentOwner.setTelephone(normalizeTelephone(ownerFieldsDto.getTelephone()));
463	        currentOwner.setEmail(normalizeEmail(ownerFieldsDto.getEmail()));
464	        this.clinicService.saveOwner(currentOwner);
465	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
466	    }
467	
468	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
469	    @Transactional
470	    @Override
471	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
472	        Owner owner = this.clinicService.findOwnerById(ownerId);
473	        if (owner == null) {
474	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
475	        }
476	        this.clinicService.deleteOwner(owner);
477	        return new ResponseEntity<>(HttpStatus.NO_CONTENT);
478	    }
479	
480	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
481	    @Override
482	    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
483	        Owner owner = this.clinicService.findOwnerById(ownerId);
484	        if (owner == null) {
485	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
486	        }
487	        HttpHeaders headers = new HttpHeaders();
488	        Pet pet = petMapper.toPet(petFieldsDto);
489	        owner.setId(ownerId);
490	        pet.setOwner(owner);
491	        pet.getType().setName(null);
492	        this.clinicService.savePet(pet);
493	        PetDto petDto = petMapper.toPetDto(pet);
494	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/pets/{id}")
495	            .buildAndExpand(pet.getId()).toUri());
496	        return new ResponseEntity<>(petDto, headers, HttpStatus.CREATED);
497	    }
498	
499	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
500	    @Override
501	    public ResponseEntity<Void> updateOwnersPet(Integer ownerId, Integer petId, PetFieldsDto petFieldsDto) {
502	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
503	        if (currentOwner != null) {
504	            Pet currentPet = this.clinicService.findPetById(petId);
505	            if (currentPet != null) {
506	                currentPet.setBirthDate(petFieldsDto.getBirthDate());
507	                currentPet.setName(petFieldsDto.getName());
508	                currentPet.setType(petMapper.toPetType(petFieldsDto.getType()));
509	                this.clinicService.savePet(currentPet);
510	                return new ResponseEntity<>(HttpStatus.NO_CONTENT);
511	            }
512	        }
513	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
514	    }
