532	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
533	    @Override
534	    public ResponseEntity<PetDto> getOwnersPet(Integer ownerId, Integer petId) {
535	        Owner owner = this.clinicService.findOwnerById(ownerId);
536	        if (owner != null) {
537	            Pet pet = owner.getPet(petId);
538	            if (pet != null) {
539	                return new ResponseEntity<>(petMapper.toPetDto(pet), HttpStatus.OK);
540	            }
541	        }
542	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
543	    }
